cypher:
MATCH (e:PlantItem {tag: 'E-41-1'})
MATCH (u:Valve)-[:line_to*1..]->(e)
WHERE NOT EXISTS {
  MATCH (u)-[:line_to*1..]->(v:Valve)
  WHERE v <> u AND EXISTS { MATCH (v)-[:line_to*1..]->(e) }
}
RETURN DISTINCT u.tag AS tag
ORDER BY tag

